   199→
   200→				output += 'l ';
   201→
   202→				for ( let j = 1, l = vertices.count; j <= l; j ++ ) {
   203→
   204→					output += ( indexVertex + j ) + ' ';
   205→
   206→				}
   207→
   208→				output += '\n';
   209→
   210→			}
   211→
   212→			if ( type === 'LineSegments' ) {
   213→
   214→				for ( let j = 1, k = j + 1, l = vertices.count; j < l; j += 2, k = j + 1 ) {
