import fs from 'fs';
import path from 'path';

// Build the scene
const root = createScene();

// Apply -90 degree X rotation for Blender Z-up coordinate space
const rotationMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
root.applyMatrix4(rotationMatrix);

// Force full world matrix update from root down
root.updateMatrixWorld(true);

// --- Custom OBJ exporter that handles InstancedMesh and negative-scale winding ---

let output = '';
let indexVertex = 0;
let indexNormals = 0;
let indexVertexUvs = 0;

const vertex = new THREE.Vector3();
const normal = new THREE.Vector3();
const uv = new THREE.Vector2();

function determinantSign(matrix4) {
  const te = matrix4.elements;
  const a = te[0], b = te[4], c = te[8];
  const d = te[1], e = te[5], f = te[9];
  const g = te[2], h = te[6], k = te[10];
  const det = a * (e * k - f * h) - b * (d * k - f * g) + c * (d * h - e * g);
  return det < 0 ? -1 : 1;
}

function writeMesh(geometry, worldMatrix, objectName) {
  let nbVertex = 0;
  let nbNormals = 0;
  let nbVertexUvs = 0;

  const normalMatrixWorld = new THREE.Matrix3();
  const det = determinantSign(worldMatrix);

  const vertices = geometry.getAttribute('position');
  const normals = geometry.getAttribute('normal');
  const uvs = geometry.getAttribute('uv');
  const indices = geometry.getIndex();

  output += 'o ' + objectName + '\n';

  // Vertices
  if (vertices !== undefined) {
    for (let i = 0, l = vertices.count; i < l; i++, nbVertex++) {
      vertex.fromBufferAttribute(vertices, i);
      vertex.applyMatrix4(worldMatrix);
      output += 'v ' + vertex.x + ' ' + vertex.y + ' ' + vertex.z + '\n';
    }
  }

  // UVs
  if (uvs !== undefined) {
    for (let i = 0, l = uvs.count; i < l; i++, nbVertexUvs++) {
      uv.fromBufferAttribute(uvs, i);
      output += 'vt ' + uv.x + ' ' + uv.y + '\n';
    }
  }

  // Normals
  if (normals !== undefined) {
    normalMatrixWorld.getNormalMatrix(worldMatrix);
    for (let i = 0, l = normals.count; i < l; i++, nbNormals++) {
      normal.fromBufferAttribute(normals, i);
      normal.applyMatrix3(normalMatrixWorld).normalize();
      output += 'vn ' + normal.x + ' ' + normal.y + ' ' + normal.z + '\n';
    }
  }

  // Faces
  const face = [];
  if (indices !== null) {
    for (let i = 0, l = indices.count; i < l; i += 3) {
      for (let m = 0; m < 3; m++) {
        // If determinant is negative (mirrored), reverse winding: 0,2,1 instead of 0,1,2
        const windingM = det < 0 ? (m === 0 ? 0 : (m === 1 ? 2 : 1)) : m;
        const j = indices.getX(i + windingM) + 1;
        face[m] = (indexVertex + j) +
          (normals || uvs
            ? '/' + (uvs ? (indexVertexUvs + j) : '') +
              (normals ? '/' + (indexNormals + j) : '')
            : '');
      }
      output += 'f ' + face.join(' ') + '\n';
    }
  } else {
    for (let i = 0, l = vertices.count; i < l; i += 3) {
      for (let m = 0; m < 3; m++) {
        const windingM = det < 0 ? (m === 0 ? 0 : (m === 1 ? 2 : 1)) : m;
        const j = i + windingM + 1;
        face[m] = (indexVertex + j) +
          (normals || uvs
            ? '/' + (uvs ? (indexVertexUvs + j) : '') +
              (normals ? '/' + (indexNormals + j) : '')
            : '');
      }
      output += 'f ' + face.join(' ') + '\n';
    }
  }

  indexVertex += nbVertex;
  indexVertexUvs += nbVertexUvs;
  indexNormals += nbNormals;
}

// Traverse the scene graph
root.traverse(function (child) {
  if (child.isInstancedMesh === true) {
    // Handle InstancedMesh: export each instance as a separate mesh object
    const instanceMatrix = new THREE.Matrix4();
    const composedMatrix = new THREE.Matrix4();
    for (let i = 0; i < child.count; i++) {
      child.getMatrixAt(i, instanceMatrix);
      // Compose: parentWorldMatrix * instanceLocalMatrix
      composedMatrix.multiplyMatrices(child.matrixWorld, instanceMatrix);
      writeMesh(child.geometry, composedMatrix, child.name + '_' + i);
    }
  } else if (child.isMesh === true) {
    writeMesh(child.geometry, child.matrixWorld, child.name);
  }
});

// Write to file
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}
fs.writeFileSync(path.join(outputDir, 'object.obj'), output);
console.log('Exported to /root/output/object.obj');

